SELECT COUNT(DISTINCT eixo_1.calculation_838513981462429699) AS ctd:calculation_838513981462429699:ok,   eixo_1.ead AS ead,   eixo_1.edital AS edital,   eixo_1.forma_ingresso AS forma_ingresso,   eixo_1.no_modalidade AS no_modalidade,   CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) AS yr:data_de_inicio:ok FROM eixo_1 WHERE ((CAST(EXTRACT(YEAR FROM eixo_1.data_de_inicio) AS BIGINT) = 2015) AND (NOT ((eixo_1.nome da sit matricula (situacao detalhada) IN ('CANC_DESISTENTE', 'CANC_MAT_PRIM_OPCAO', 'CANC_SANÇÃO', 'CANC_SEM_FREQ_INICIAL', 'CANC_TURMA', 'DOC_INSUFIC', 'ESCOL_INSUFIC', 'INC _ITINERARIO', 'INSC_CANC', 'Não Matriculado', 'NÃO_COMPARECEU', 'TURMA_CANC', 'VAGAS_INSUFIC')) OR (eixo_1.nome da sit matricula (situacao detalhada) IS NULL))) AND (NOT (eixo_1.situacao_da_turma IN ('CANCELADA', 'CRIADA', 'PUBLICADA')))) GROUP BY ead,   edital,   forma_ingresso,   no_modalidade,   yr:data_de_inicio:ok;
